package android.os;import java.util.*;public class Handler {public static final List<Runnable> queue=new ArrayList<>();public Handler(Looper l){}public void post(Runnable r){queue.add(r);}public void postDelayed(Runnable r,long l){}public void removeCallbacks(Runnable r){queue.remove(r);}public void removeCallbacksAndMessages(Object o){queue.clear();}public static void drain(){while(!queue.isEmpty())queue.remove(0).run();} }